function factorial(n) {
  const primes = [2,3,5,7];
  const exponents = {};
  for (const p of primes) {
    let exp = 0;
    let current = n;
    while (current > 0) {
      current = Math.floor(current / p);
      exp += current;
    }
    exponents[p] = exp;
  }
  return exponents;
}

function decompose(primeExponents) {
  const digits = [];
  let e2 = primeExponents[2];
  let e3 = primeExponents[3];
  let e5 = primeExponents[5];
  let e7 = primeExponents[7];

  while (e7 > 0) {
    digits.push(7);
    e7--;
  }
  while (e5 > 0) {
    digits.push(5);
    e5--;
  }
  while (e3 > 0) {
    digits.push(3);
    e3--;
  }
  while (e2 > 0) {
    digits.push(2);
    e2--;
  }
  return digits;
}
